item.command:
/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
files=sorted(Path('/mnt/data/LSF/data/court/text').glob('*.txt'))
patterns=[r'Argued and Submitted', r'Submitted on the briefs', r'Submitted [A-Z][a-z]+ [0-9]{1,2}, [0-9]{4}', r'Argued [A-Z][a-z]+ [0-9]{1,2}, [0-9]{4}']
counts={p:0 for p in patterns}
examples={p:[] for p in patterns}
for p in files:
    txt=p.read_text(errors='ignore')
    for pat in patterns:
        if re.search(pat, txt):
            counts[pat]+=1
            if len(examples[pat])<5:
                examples[pat].append(p.name)
for pat in patterns:
    print('PATTERN', pat, 'COUNT', counts[pat], 'EXAMPLES', examples[pat])
PY"

